/** C ref: mkmaze.c:950 — @param {CInt} corrwid @param {CInt} wallthick @param {CInt} rmdeadends */
export function* create_maze(corrwid, wallthick, rmdeadends) {
    let x;
    let y;
    let mm = cptr.alloc(4);
    let tmp_xmax = cptr.ldI32(gx);
    let tmp_ymax = cptr.ldI32(gy);
    let rdx = 0;
    let rdy = 0;
    let scale;

    if (corrwid == -1)
        corrwid = rnd(4);

    if (wallthick == -1)
        wallthick = (rnd(4) - corrwid) | 0;

    if (wallthick < 1)
        wallthick = 1;
    else if (wallthick > 5)
        wallthick = 5;

    if (corrwid < 1)
        corrwid = 1;
    else if (corrwid > 5)
        corrwid = 5;

    scale = (corrwid + wallthick) | 0;
    rdx = ((cptr.ldI32(gx) / scale) | 0);
    rdy = ((cptr.ldI32(gy) / scale) | 0);

    if ((cptr.ldI32o(
        svl,
        $instance_globals_saved_l_level + $dlevel_t_flags + $levelflags_corrmaze
    ) & 1))
        for (x = 2; x < (Math.imul(rdx, 2)); x++)
            for (y = 2; y < (Math.imul(rdy, 2)); y++)
                cptr.st1o3(
                    svl,
                    x,
                    $sizeof_rm_x21,
                    y,
                    $sizeof_rm,
                    $instance_globals_saved_l_level + $rm_typ,
                    NHC.STONE
                );
    else
        for (x = 2; x <= (Math.imul(rdx, 2)); x++)
            for (y = 2; y <= (Math.imul(rdy, 2)); y++)
                cptr.st1o3(
                    svl,
                    x,
                    $sizeof_rm_x21,
                    y,
                    $sizeof_rm,
                    $instance_globals_saved_l_level + $rm_typ,
                    schar((((x % 2) && (y % 2)) ? NHC.STONE : NHC.HWALL))
                );

    /* set upper bounds for maze0xy and walkfrom */
    cptr.stI32(gx, (Math.imul(rdx, 2)));
    cptr.stI32(gy, (Math.imul(rdy, 2)));

    /* create maze */
    maze0xy(mm);
    (yield* walkfrom(i16(cptr.ldI16(mm)), i16(cptr.ldI16o(mm, $nhcoord_y)), 0));

    if (rmdeadends)
        (yield* maze_remove_deadends(i16((((cptr.ldI32o(
            svl,
            $instance_globals_saved_l_level + $dlevel_t_flags + $levelflags_corrmaze
        ) & 1)) | 0
                ? NHC.CORR
                : NHC.ROOM))));

    /* restore bounds */
    cptr.stI32(gx, tmp_xmax);
    cptr.stI32(gy, tmp_ymax);

    /* scale maze up if needed */
    if (scale > 2) {
        let tmpmap = (function () {
            const flat = new Uint8Array(80 * (21 * 1));
            const a = [];
            for (let r = 0; r < 80; r++) a.push(flat.subarray(r * (21 * 1), (r + 1) * (21 * 1)));
            a.buf = flat;
            return a;
        })();
        let mx;
        let my;
        let dx;
        let dy;
        let rx = 1;
        let ry = 1;

        /* back up the existing smaller maze */
        for (x = 1; x < cptr.ldI32(gx); x++)
            for (y = 1; y < cptr.ldI32(gy); y++) {
                cptr.st1o(
                    cptr.decay(tmpmap[x]),
                    y,
                    cptr.ld1so3(
                        svl,
                        x,
                        $sizeof_rm_x21,
                        y,
                        $sizeof_rm,
                        $instance_globals_saved_l_level + $rm_typ
                    ),
                    1
                );
            }

        /* do the scaling */
        rx = (x = 2);
        while (rx < cptr.ldI32(gx)) {
            mx = (x % 2) ? corrwid : ((x == 2 || x == Math.imul(rdx, 2)) ? 1 : wallthick);
            ry = (y = 2);
            while (ry < cptr.ldI32(gy)) {
                my = (y % 2) ? corrwid : ((y == 2 || y == Math.imul(rdy, 2)) ? 1 : wallthick);
                for (dx = 0; dx < mx; dx++)
                    for (dy = 0; dy < my; dy++) {
                        if (((rx + dx) | 0) >= cptr.ldI32(gx) || ((ry + dy) | 0) >= cptr.ldI32(gy))
                            break;
                        cptr.st1o3(
                            svl,
                            (rx + dx) | 0,
                            $sizeof_rm_x21,
                            (ry + dy) | 0,
                            $sizeof_rm,
                            $instance_globals_saved_l_level + $rm_typ,
                            cptr.ld1so(cptr.decay(tmpmap[x]), y, 1)
                        );
                    }
                ry = (ry + my) | 0;
                y++;
            }
            rx = (rx + mx) | 0;
            x++;
        }

    }
}

